ALTER TABLE "CURRENT_TERMS" MODIFY (CAUCUS ANNOTATIONS (ADD value_description 'For independents, the party that the legislator caucuses with, using the same values as the party field. Omitted if the legislator caucuses with the party indicated in the party field. When in doubt about the difference between the party and caucus fields, the party field is what displays after the legislator''s name (i.e. "(D)") but the caucus field is what normally determines committee seniority. This field was added starting with terms for the 113th Congress.'));
