ALTER TABLE "CURRENT_TERMS" MODIFY (PARTY ANNOTATIONS (ADD value_description 'commonsense evidence:If the legislator changed parties, this is the most recent party held during the term and party_affiliations will be set. Values are typically "Democrat", "Independent", or "Republican". The value typically matches the political party of the legislator on the ballot in his or her last election, although for state affiliate parties such as "Democratic Farmer Labor" we will use the national party name ("Democrat") instead to keep the values of this field normalized.'));
COMMENT ON COLUMN "CURRENT_TERMS".PARTY_AFFILIATIONS IS 'This field is present if the legislator changed party or caucus affiliation during the term.';
ALTER TABLE "CURRENT_TERMS" MODIFY (PARTY_AFFILIATIONS ANNOTATIONS (ADD value_description 'The value is a list of time periods, with start and end dates, each of which has a party field and a caucus field if applicable, with the same meanings as the main party and caucus fields. The time periods cover the entire term, so the first start will match the term start, the last end will match the term end, and the last party (and caucus if present) will match the term party (and caucus).'));
